python
def bookingRackPeakTicket(drawers):
    a=drawers
    out=[]
    end=float('-inf')
    for s,e in sorted(a,key=lambda r:(r[1],r[0])):
        if s>=end:
            out.append(e-s)
            end=e
    return max(out,default=0)


java
class Solution {
  public int bookingRackPeakTicket(int[][] drawers) {
    int[][] a=drawers; List<Integer> out=new ArrayList<>();
    {int[][]rows=a.clone();Arrays.sort(rows,Comparator.comparingInt((int[]r)->r[1]).thenComparingInt(r->r[0]));int end=Integer.MIN_VALUE;for(int[]r:rows)if(r[0]>=end){out.add(r[1]-r[0]);end=r[1];}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
